pub struct PacketQualityScores {
    pub relevance: u8,
    pub completeness: u8,
    pub specificity: u8,
    pub freshness: u8,
    pub grounding: u8,
    pub concision: u8,
    pub noise_absence: u8,
}

impl PacketQualityScores {
    #[must_use]
